using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Searches for messages tagged by the given reaction and with the given words in the Saved Messages chat; for Telegram Premium users only.
    /// Returns the results in reverse chronological order, i.e. in order of decreasing message_id.
    /// For optimal performance, the number of returned messages is chosen by TDLib and can be smaller than the specified limit
    /// </summary>
    public Task<TdLib.TdApi.Objects.FoundChatMessages> SearchSavedMessagesAsync(long savedMessagesTopicId = default, ReactionType tag = default, string query = default, long fromMessageId = default, int offset = default, int limit = default)
    {

           using var activity =  StartCallActivity("SearchSavedMessagesAsync", typeof(SearchSavedMessages).FullName ?? "SearchSavedMessagesAsync");

           try
           {
             return client.SearchSavedMessagesAsync(savedMessagesTopicId, tag, query, fromMessageId, offset, limit);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
